/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import CarnotHeatEngineColors from "../../src/CarnotHeatEngineColors.js";
import { EfficiencyLabScreen } from "../../src/efficiency-lab/EfficiencyLabScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { IntroScreen } from "../../src/intro/IntroScreen.js";
import { CarnotHeatEnginePreferencesModel } from "../../src/preferences/CarnotHeatEnginePreferencesModel.js";
import { ReversedCycleScreen } from "../../src/reversed-cycle/ReversedCycleScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from carnotHeatEngineQueryParameters.
  // Constructed once here and handed to every Screen, because the diagrams honour
  // the "label cycle corners" toggle.
  const simPreferences = new CarnotHeatEnginePreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new IntroScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().introStringProperty,
      tandem: Tandem.ROOT.createTandem("introScreen"),
      backgroundColorProperty: CarnotHeatEngineColors.backgroundColorProperty,
    }),
    new EfficiencyLabScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().efficiencyLabStringProperty,
      tandem: Tandem.ROOT.createTandem("efficiencyLabScreen"),
      backgroundColorProperty: CarnotHeatEngineColors.backgroundColorProperty,
    }),
    new ReversedCycleScreen(simPreferences, {
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().reversedCycleStringProperty,
      tandem: Tandem.ROOT.createTandem("reversedCycleScreen"),
      backgroundColorProperty: CarnotHeatEngineColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { CarnotHeatEngineColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
